'use client';

// Vendored from MerchFlow Charts components/web/CategoryMix.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { gms, webText } from '@/lib/merch-flow-report/brand/tokens';
import { units, percent } from '@/lib/merch-flow-report/format';
import type { Product } from '@/lib/merch-flow-report/report/types';
import { categoryTotals, scorecard, CATEGORY_COLORS, categoryOf } from '@/lib/merch-flow-report/report/derive';

/**
 * Category mix and reach.
 *
 * Colours are fixed per category and come from the validated categorical
 * palette, so a category keeps its colour no matter how the list is sorted.
 */
export function CategoryMix({
  products,
  attendance,
}: {
  products: Product[];
  attendance: number;
}) {
  const totals = categoryTotals(products);
  const reach = scorecard(products).slice(0, 10);
  const maxReach = attendance > 0 ? Math.max(...reach.map((p) => p.unitsSold / attendance), 0.0001) : 1;

  return (
    <div>
      <p className="mb-4 max-w-[75ch] text-[13px] leading-relaxed" style={{ color: webText.secondary }}>
        Share of units by category, then the share of the audience that bought each
        of the ten best-selling products.
      </p>

      <div className="flex h-9 w-full overflow-hidden rounded">
        {totals.map((total) => (
          <div
            key={total.category}
            className="flex items-center overflow-hidden whitespace-nowrap px-2 text-[13px] font-bold text-white"
            style={{ width: `${total.share * 100}%`, background: total.color }}
            title={`${total.category}: ${percent(total.share, 1)}`}
          >
            {total.share > 0.06 ? percent(total.share, 0) : ''}
          </div>
        ))}
      </div>

      <ul className="mt-3 flex flex-wrap gap-x-5 gap-y-1.5 text-[13px]">
        {totals.map((total) => (
          <li key={total.category} className="flex items-center gap-1.5">
            <span
              className="inline-block h-2.5 w-2.5 rounded-[2px]"
              style={{ background: total.color }}
            />
            <span className="font-semibold">{total.category}</span>
            <span className="tnum" style={{ color: webText.secondary }}>
              {units(total.units)} · {total.products} products
            </span>
          </li>
        ))}
      </ul>

      {attendance > 0 && (
        <div className="mt-7" data-tour="mf-ratios">
          <h3
            className="border-b pb-1.5 text-[12px] font-bold uppercase tracking-[0.12em]"
            style={{ color: gms.red, borderColor: gms.border }}
          >
            Reach · share of audience
          </h3>
          <ul>
            {reach.map((product) => {
              const share = product.unitsSold / attendance;
              const category = product.category ?? categoryOf(product);
              return (
                <li
                  key={product.sku}
                  className="flex items-center gap-2 border-b py-1.5 sm:gap-3"
                  style={{ borderColor: '#F0F0F0' }}
                >
                  <span className="min-w-0 flex-1 truncate text-[13px] text-ink">
                    {product.displayName ?? product.name}
                  </span>
                  <span className="relative hidden h-2.5 w-28 shrink-0 sm:block lg:w-40">
                    <span
                      className="absolute inset-0 rounded"
                      style={{ background: '#E4E6E9' }}
                    />
                    <span
                      className="absolute left-0 top-0 h-full rounded"
                      style={{
                        width: `${(share / maxReach) * 100}%`,
                        background: CATEGORY_COLORS[category],
                      }}
                    />
                  </span>
                  <span className="tnum w-20 shrink-0 text-right text-[13px]" style={{ color: webText.secondary }}>
                    1 in {Math.round(1 / share).toLocaleString('en-US')}
                  </span>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
}
